"""dataset.py: Dataset class for loading rendered views and camera poses from the dataset generated by render_scene.py."""

from pathlib import Path
import csv

import numpy as np
import torch
from PIL import Image
from torch.utils.data import Dataset
from torch.utils.data._utils.collate import default_collate
from torchvision import transforms

from .render_scene import generate_random_cameras, look_at


default_transform = transforms.Compose(
    [
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.0, 0.0, 0.0], std=[1.0, 1.0, 1.0]),
    ]
)


class CameraDataset(Dataset):
    """Sample fresh OpenGL cameras on a sphere for each requested item.

    num_cameras specifies the number of samples per epoch, not a stored bank.
    """

    def __init__(self, source, source_pose, intrinsics, num_cameras=128, radius=2.0, seed=42):
        self.source = source.detach().cpu().clone()
        self.source_pose = source_pose.detach().cpu().clone()
        self.intrinsics = intrinsics.detach().cpu().clone()
        self.num_cameras = num_cameras
        self.radius = radius
        self.rng = np.random.default_rng(seed)

    def __len__(self):
        return self.num_cameras

    def __getitem__(self, index):
        _, position, up = generate_random_cameras(
            num_views=1, radius=self.radius, rng=self.rng
        )[0]
        pose = look_at(position, np.zeros(3, dtype=np.float32), up=up)
        return {
            "image": self.source,
            "source": self.source_pose,
            "target": torch.from_numpy(pose),
            "intrinsics": self.intrinsics,
        }

    def getitems(self, indices):
        return default_collate([self[int(index)] for index in indices])


class ViewDataset(Dataset):
    def __init__(
        self,
        root,
        split="training",
        mode="rotate",
        transform=default_transform,
        target_transform=default_transform,
        random_matching=True,
        use_encoding=False,
        use_depth=False,
        max_images=None,
    ):
        self.root = Path(root) / split
        self.transform = transform
        self.target_transform = target_transform
        self.split = split
        self.mode = mode
        self.random_matching = random_matching
        self.use_encoding = use_encoding
        self.use_depth = use_depth
        self.samples = []
        self.scene_info = {}
        self.scene_depths = {}
        self.scene_intrinsics = {}

        if not self.root.exists():
            raise FileNotFoundError(f"Dataset split not found: {self.root}")

        scene_dirs = sorted(p for p in self.root.iterdir() if p.is_dir())
        if not scene_dirs:
            raise ValueError(f"No scene directories found in {self.root}")

        for scene_dir in scene_dirs:
            image_list = []
            depth_list = []
            csv_path = scene_dir / "camera_matrices.csv"
            intrinsic_path = scene_dir / "intrinsics.csv"
            if not csv_path.exists():
                raise FileNotFoundError(f"camera_matrices.csv not found in {scene_dir}")
            if not intrinsic_path.exists():
                raise FileNotFoundError(f"intrinsics.csv not found in {scene_dir}")
            idx = 0
            with open(csv_path, newline="") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    if self.use_encoding:
                        filename = row.get("encoded_filename")
                    else:
                        filename = row.get("filename")
                    if not filename:
                        continue
                    mat = np.zeros((4, 4), dtype=np.float32)
                    for j in range(16):
                        mat.flat[j] = float(row.get(f"m{j}", 0.0))
                    img_path = scene_dir / filename
                    if img_path.exists():
                        if self.use_depth:
                            depth_filename = row.get("depth_filename")
                            depth_path = (
                                scene_dir / depth_filename if depth_filename else None
                            )
                            if depth_path is None or not depth_path.exists():
                                raise FileNotFoundError(
                                    f"depth_filename is missing or invalid for {img_path}; "
                                    "regenerate this dataset with the updated renderer"
                                )
                            depth_list.append(depth_path)
                        image_list.append((img_path, mat))
            with open(intrinsic_path, newline="") as f:
                reader = csv.reader(f)
                intrinsics = []
                for row in reader:
                    intrinsics.append([float(x) for x in row])
                intrinsics = np.array(intrinsics, dtype=np.float32)
            if len(image_list) <= 1:
                raise ValueError(
                    f"Not enough images listed in camera_matrices.csv for {scene_dir}"
                )
            self.scene_info[scene_dir] = image_list
            if self.use_depth:
                self.scene_depths[scene_dir] = depth_list
            self.scene_intrinsics[scene_dir] = intrinsics
            for idx in range(len(image_list)):
                if max_images is not None and len(self.samples) >= max_images:
                    break
                self.samples.append((scene_dir, idx))
            if max_images is not None and len(self.samples) >= max_images:
                break

        if not self.samples:
            raise ValueError(f"No valid image samples found in {self.root}")

    def __len__(self):
        return len(self.samples)

    def _load_encoding(self, encoding_path):
        if not encoding_path.exists():
            raise FileNotFoundError(
                f"Encoded representation not found: {encoding_path}"
            )
        encoding = torch.load(encoding_path)
        return encoding.squeeze(0)

    def _load_image(self, path, transform):
        image = Image.open(path).convert("RGB")
        image = transform(image)
        return image

    def _load_depth(self, path):
        if Path(path).suffix == ".npz":
            with np.load(path, allow_pickle=False) as archive:
                depth = archive["depth"].astype(np.float32)
        else:
            depth = np.load(path, allow_pickle=False).astype(np.float32, copy=False)
        if depth.ndim != 2:
            raise ValueError(f"expected a 2D depth map in {path}, got {depth.shape}")
        return torch.from_numpy(depth)

    def __getitem__(self, idx):
        scene_dir, img_idx = self.samples[idx]
        image_list = self.scene_info[scene_dir]

        input_path, input_pose = image_list[img_idx]
        intrinsics = self.scene_intrinsics[scene_dir]
        input_pose, intrinsics = (
            torch.from_numpy(input_pose),
            torch.from_numpy(intrinsics),
        )

        # choose target depending on split
        if self.random_matching:
            while True:
                next_idx = np.random.randint(0, len(image_list))
                if next_idx != img_idx:
                    break
        else:
            next_idx = (img_idx + 1) % len(image_list)

        target_path, target_pose = image_list[next_idx]
        target_pose = torch.from_numpy(target_pose)

        if self.use_encoding:
            input_image = self._load_encoding(input_path)
            target_image = self._load_encoding(target_path)
        else:
            input_image = self._load_image(input_path, self.transform)
            target_image = self._load_image(target_path, self.target_transform)

        # In raw mode, form RGB-D so the autoencoder can encode all four channels.
        # In encoded mode, the .pt tensors are already RGB-D latents and must not
        # receive another raw depth channel.
        if self.use_depth and not self.use_encoding:
            input_depth = self._load_depth(self.scene_depths[scene_dir][img_idx])
            target_depth = self._load_depth(self.scene_depths[scene_dir][next_idx])
            input_image = torch.cat([input_image, input_depth.unsqueeze(0)], dim=0)
            target_image = torch.cat([target_image, target_depth.unsqueeze(0)], dim=0)

        if self.mode == "rotate" or self.mode == "generate":
            return input_image, target_image, input_pose, target_pose, intrinsics
        elif self.mode == "encode":
            return input_image
        else:
            raise ValueError(f"Invalid mode: {self.mode}")

    def getitems(self, indices):
        if isinstance(indices, torch.Tensor):
            if indices.ndim == 0:
                return self[indices.item()]
            indices = indices.tolist()
        elif isinstance(indices, np.ndarray):
            if indices.ndim == 0:
                return self[int(indices.item())]
            indices = indices.tolist()

        if isinstance(indices, (int, np.integer)):
            return self[int(indices)]

        return default_collate([self[idx] for idx in indices])
